import {
  AlignmentType,
  Document,
  Packer,
  PageOrientation,
  Paragraph,
  Table,
  TableCell,
  TableRow,
  TextRun,
  UnderlineType,
  VerticalAlign,
  WidthType,
} from 'docx';
import saveAs from 'file-saver';
import type { TranslationPair } from '../types';

// Helper to sanitize filenames.
// Removes invalid characters, collapses whitespace to single spaces, and trims.
const sanitizeFilename = (name: string): string => {
  return name.replace(/[^a-z0-9\s-]/gi, '').trim().replace(/\s+/g, ' ').slice(0, 50) || 'translation';
};

// Helper to convert a string to Title Case.
const toTitleCase = (str: string): string => {
  if (!str) return '';
  return str
    .toLowerCase()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

export const exportToWord = (data: TranslationPair[]): void => {
  if (!data || data.length === 0) {
    console.error("No data available to export.");
    return;
  }

  const titlePair = data[0];
  const bodyPairs = data.length > 1 ? data.slice(1) : [];

  const FONT_FAMILY = 'Arial';
  const FONT_SIZE_PT = 24;
  const FONT_SIZE_HALF_PT = FONT_SIZE_PT * 2;

  const englishTitleText = toTitleCase(titlePair.english);

  // --- Create Title Paragraphs ---
  const arabicTitle = new Paragraph({
    alignment: AlignmentType.CENTER,
    bidirectional: true,
    children: [new TextRun({
      text: titlePair.arabic,
      font: FONT_FAMILY,
      size: FONT_SIZE_HALF_PT,
      bold: true,
      underline: { type: UnderlineType.SINGLE },
      rtl: true,
    })],
  });

  const englishTitle = new Paragraph({
    alignment: AlignmentType.CENTER,
    children: [new TextRun({
      text: englishTitleText,
      font: FONT_FAMILY,
      size: FONT_SIZE_HALF_PT,
      bold: true,
      underline: { type: UnderlineType.SINGLE },
    })],
  });

  const spacer = new Paragraph({ text: '' });

  // --- Create Body Table ---
  const tableRows = bodyPairs.map(pair => new TableRow({
    // cantSplit ensures that the row does not break across pages.
    cantSplit: true,
    children: [
      // Arabic Cell
      new TableCell({
        verticalAlign: VerticalAlign.TOP,
        children: [new Paragraph({
          bidirectional: true,
          children: [new TextRun({
            text: pair.arabic,
            font: FONT_FAMILY,
            size: FONT_SIZE_HALF_PT,
            rtl: true,
          })],
        })],
      }),
      // English Cell
      new TableCell({
        verticalAlign: VerticalAlign.TOP,
        children: [new Paragraph({
          alignment: AlignmentType.LEFT,
          children: [new TextRun({
            text: pair.english,
            font: FONT_FAMILY,
            size: FONT_SIZE_HALF_PT,
          })],
        })],
      }),
    ],
  }));

  // For landscape orientation, a standard Letter page is 11" x 8.5".
  // 1 inch = 1440 twips (DXA).
  // With 0.5-inch margins (720 twips each), usable width is 10 inches = 14400 twips.
  const tableWidth = 14400;
  const columnWidth = tableWidth / 2;

  const bodyTable = new Table({
    rows: tableRows,
    width: { size: tableWidth, type: WidthType.DXA },
    columnWidths: [columnWidth, columnWidth],
  });

  // --- Assemble Document ---
  const doc = new Document({
    sections: [{
      properties: {
        page: {
          size: {
            // Explicitly set page dimensions for landscape for maximum compatibility.
            // US Letter Landscape: 11" x 8.5"
            width: 15840,  // 11 inches in twips
            height: 12240, // 8.5 inches in twips
          },
          orientation: PageOrientation.LANDSCAPE,
          margin: { top: 720, right: 720, bottom: 720, left: 720 }, // 0.5 inch in twips
        },
      },
      children: [
        arabicTitle,
        englishTitle,
        spacer,
        ...(bodyPairs.length > 0 ? [bodyTable] : []),
      ],
    }],
  });

  // --- Generate and Download ---
  Packer.toBlob(doc).then(blob => {
    const baseFilename = sanitizeFilename(englishTitleText);
    const filename = `${baseFilename} (Arabic + English).docx`;
    saveAs(blob, filename);
  }).catch(error => {
    console.error("Error generating Word document:", error);
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { TranslationPair } from '../types';

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const translationSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      arabic: {
        type: Type.STRING,
        description: "The original Arabic sentence or phrase.",
      },
      english: {
        type: Type.STRING,
        description: "The corresponding English translation.",
      },
    },
    required: ["arabic", "english"],
  },
};

export const translateAndAlignText = async (text: string): Promise<TranslationPair[]> => {
  const prompt = `
    You are an expert translator specializing in Arabic to English.
    Your task is to take the provided Arabic text, translate it accurately into English, and segment the output based on the paragraph structure of the original text.
    Treat any block of text separated by one or more empty lines as a distinct paragraph or segment.
    The first segment should represent the title or the very first line of the source text.
    For each segment you identify, create a corresponding translation.

    CRITICAL: If a segment contains internal single line breaks (but not empty lines), preserve those as newline characters (\\n) in both the 'arabic' and 'english' fields of your JSON response. This ensures formatting is maintained within the same row.

    If the text appears to be from a religious text like the Bible, please ensure the English translation aligns with a well-known version like the New King James Version (NKJV) where appropriate.
    The final output must be a valid JSON array of objects.

    Here is the Arabic text:
    ---
    ${text}
    ---
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: translationSchema,
      },
    });

    const jsonString = response.text;
    const result = JSON.parse(jsonString);
    return result as TranslationPair[];
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to translate and align text. The model may have returned an invalid response.");
  }
};

